proc decomposeCall(ctx: var Context, call: Atom, requireTopLevel: bool): (Atom, DecompositionStatus) {.nimcall.} =
  let empty = emptyList()
  if ctx.execution == nil or ctx.prepared == nil: return (empty, dsInvalidContext)
  let ex = ctx.execution
  ex.resetDiagnostics()
  if ctx.worldState == nil or ctx.bindings == nil: return (empty, dsInvalidContext)
  if not call.isKind(akList) or call.len < 1: return (empty, dsInvalidCall)
  let head = call.at(0)[0]
  if not head.isKind(akSymbol): return (empty, dsInvalidCall)
  let argumentCount = call.len - 1
  ex.begin(ctx, factSymbols, callNames)
  var entry = -1
  if entry < 0 and head.symbolValue == sym6 and argumentCount == 0:
    entry = 4
  if entry < 0 and head.symbolValue == sym7 and argumentCount == 3:
    entry = 5
  if entry < 0 and head.symbolValue == sym8 and argumentCount == 0:
    entry = 6
  if entry < 0 and head.symbolValue == sym9 and argumentCount == 0:
    entry = 7
  if entry < 0: return (empty, dsInvalidCall)
  ex.debugBeginPlan(definition, uint32(entry))
  var runResult = 0
  case entry
  of 4:
    runResult = ex.run(method4)
  of 5:
    block:
      let argument = call.at(1)[0]
      if not argument.isBound: return (empty, dsInvalidCall)
      ex.v[2] = argument
    block:
      let argument = call.at(2)[0]
      if not argument.isBound: return (empty, dsInvalidCall)
      ex.v[3] = argument
    block:
      let argument = call.at(3)[0]
      if not argument.isBound: return (empty, dsInvalidCall)
      ex.v[4] = argument
    runResult = ex.run(method5)
  of 6:
    runResult = ex.run(method6)
  of 7:
    runResult = ex.run(method7)
  else: discard
  if runResult == 0:
    ex.debugEndPlan(definition, false)
    return (empty, ex.failureState)
  while ex.pendingCount != 0:
    let next = ex.popPending()
    if next == nil: break
    if ex.run(next) == 0:
      ex.debugEndPlan(definition, false)
      return (empty, ex.failureState)
  ex.debugEndPlan(definition, true)
  (ex.planAtom(), dsSucceeded)

